"""PyTorch fallback for paged-KV metadata construction."""

import torch


def build_paged_kv_metadata_torch(
    page_table: torch.Tensor,
    batch_idx: torch.Tensor,
    input_pos: torch.Tensor,
    out_page_table: torch.Tensor,
    out_seqused_k: torch.Tensor,
    page_size: int,
) -> None:
    batch_size = int(batch_idx.shape[0])
    if batch_size == 0:
        return

    n_pages = int(page_table.shape[1])
    batch_idx_i64 = batch_idx.to(dtype=torch.long)
    seqlen = input_pos.to(dtype=torch.long) + 1
    num_pages = ((seqlen + (int(page_size) - 1)) // int(page_size)).clamp(max=n_pages)

    rows = page_table.index_select(0, batch_idx_i64)
    row_view = out_page_table[:batch_size, :n_pages]
    valid_mask = (
        torch.arange(n_pages, device=row_view.device).unsqueeze(0)
        < num_pages.unsqueeze(1)
    )
    row_view[valid_mask] = rows[valid_mask]
    out_seqused_k[:batch_size].copy_(seqlen.to(dtype=torch.int32))


__all__ = ["build_paged_kv_metadata_torch"]
